Clase Sensor
    Privado Definir temperatura Como Entero;

    Metodo Constructor(unaTemperatura Como Entero)
        Este.temperatura <- unaTemperatura;
    FinMetodo

    Publico Metodo Temperatura() Como Entero
        Retornar Este.temperatura;
    FinMetodo
FinClase

Clase Termostato
    Privado Definir sensor Como Sensor;

    Metodo Constructor(unaTemperatura Como Entero)
        Este.sensor <- Nuevo Sensor(unaTemperatura);
    FinMetodo

    Publico Metodo EstaCaliente() Como Entero
        Si Este.sensor.Temperatura() > 25 Entonces
            Retornar 1;
        SiNo
            Retornar 0;
        FinSi
    FinMetodo
FinClase

Proceso ProbarTermostato
    Definir temperatura Como Entero;
    Definir termostato Como Termostato;
    Leer temperatura;
    termostato <- Nuevo Termostato(temperatura);
    Escribir termostato.EstaCaliente();
FinProceso
